#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int longestSubarray(vector<int>& nums, int k) {
        unordered_map<int, int> freq;
        int left = 0, repeated = 0, ans = 0;

        for (int right = 0; right < nums.size(); right++) {
            freq[nums[right]]++;

            if (freq[nums[right]] == 2)
                repeated++;

            while (repeated > k) {
                freq[nums[left]]--;

                if (freq[nums[left]] == 1)
                    repeated--;

                left++;
            }

            ans = max(ans, right - left + 1);
        }

        return ans;
    }
};

#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int earliestFinishTime(vector<int>& landStart, vector<int>& landDur,
                           vector<int>& waterStart, vector<int>& waterDur) {
        int ans = INT_MAX;

        for (int i = 0; i < landStart.size(); i++) {
            int landEnd = landStart[i] + landDur[i];

            for (int j = 0; j < waterStart.size(); j++) {
                int start = max(landEnd, waterStart[j]);
                ans = min(ans, start + waterDur[j]);
            }
        }

        return ans;
    }
};

#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int maxWeight(vector<int>& weights) {
        sort(weights.begin(), weights.end(), greater<int>());

        int n = weights.size();
        int bag1 = 0, bag2 = 0;

        for (int i = 0; i < n / 2; i++)
            bag1 += weights[i];

        for (int i = n / 2; i < n; i++)
            bag2 += weights[i];

        return abs(bag1 - bag2);
    }
};

#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int maxBalancedShipments(vector<int>& weight) {
        int ans = 0;
        int mn = weight[0];

        for (int i = 1; i < weight.size(); i++) {
            if (weight[i] > mn) {
                ans++;
                mn = INT_MAX;
            } else {
                mn = min(mn, weight[i]);
            }
        }

        return ans;
    }
};

#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int trionic(vector<int>& nums) {
        int n = nums.size();
        vector<int> inc(n, 1), dec(n, 1);

        for (int i = 1; i < n; i++) {
            if (nums[i] > nums[i - 1])
                inc[i] = inc[i - 1] + 1;
        }

        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] > nums[i + 1])
                dec[i] = dec[i + 1] + 1;
        }

        int ans = 0;

        for (int i = 0; i < n; i++)
            ans = max(ans, inc[i] + dec[i] - 1);

        return ans;
    }
};

#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    bool isPalindrome(long long n) {
        long long rev = 0, temp = n;

        while (temp > 0) {
            rev = rev * 10 + temp % 10;
            temp /= 10;
        }

        return rev == n;
    }

    long long nextPalindrome(long long n) {
        n++;

        while (!isPalindrome(n))
            n++;

        return n;
    }
};

#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<vector<int>> sortThreats(vector<vector<int>>& threats) {
        sort(threats.begin(), threats.end(), [](vector<int>& a, vector<int>& b) {
            if (a[0] != b[0])
                return a[0] > b[0];
            return a[1] > b[1];
        });

        return threats;
    }
};
